/*
 * Root abstract class -- used to implement some overall 'default' methods. 
 */
public abstract class GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
    public static int ENUM_ID_NOT_EXIST = -1;
    public static str PATH_NOT_EXIST = 'PATH_NOT_EXIST';

}

Method.Source:
public Common getRecord(Common _pricingObject)
{
    // All pricing attribute contains a method called 'getTableRecord'.
    ClassId clazzId = classIdGet(this);
    DictClass attributeClass = new DictClass(classIdGet(this));
    Common record = attributeClass.callObject("getTableRecord", this, _pricingObject);
    return record;
}

public abstract Query buildPricingObjectQuery(Query _query, anytype _value, Map _qbdsMap = null)
{
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    // Default implementation -- Add simple value check for the pricing attribute's table & field.
    // Overwrite this if special query is required.

    // <param name = "_qbds">datasource build from the table class</param>
    // <param name = "_value">value to be searched</param>
    QueryBuildRange qbr;

    DictClass dc = new DictClass(classIdGet(this));
    GUPPricingAttributeFieldsDiscoveryAttribute attribute = (dc.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute') as GUPPricingAttributeFieldsDiscoveryAttribute);
    str fieldName = attribute.parmFieldName();

    DictTable dictTable = new DictTable(tableName2Id(this.getQueryBuilderDatasourceIdentifier()));
    qbr = _qbds.addRange(dictTable.fieldName2Id(fieldName));
    qbr.value(_value);
}

public Set getAllowedValues()
{
    // Notice: all enum are have data type of String.
    if (this.getFixedAllowedValueEnumId() != ENUM_ID_NOT_EXIST)
    {
        Set allowedValues = new Set(Types::String);
        allowedValues.add("");

        DictEnum dictEnum = new DictEnum(this.getFixedAllowedValueEnumId());

        for (int i = 0; i < dictEnum.values(); i++)
        {
            allowedValues.add(dictEnum.value2Symbol(i));
        }

        return allowedValues;
    }
    // Get allowed values for non-enum table field.
    else
    {
        DictClass dc = new DictClass(classIdGet(this));
        GUPPricingAttributeFieldsDiscoveryAttribute attribute = (dc.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute') as GUPPricingAttributeFieldsDiscoveryAttribute);

        str tableName, fieldName;
        if (attribute.parmFieldAllowedValueAlternativeTableName() == "")
        {
            tableName = this.getQueryBuilderDatasourceIdentifier();
            fieldName = attribute.parmFieldName();
        }
        else
        {
            tableName = attribute.parmFieldAllowedValueAlternativeTableName();
            fieldName = attribute.parmFieldAllowedValueAlternativeFieldName();
        }

        DictTable attrTable = new DictTable(tableName2Id(tableName));
        DictField attrField = new DictField(attrTable.id(), fieldName2Id(attrTable.id(), fieldName));

        Query allowValuesQuery = new Query();
        QueryBuildDataSource qbdsRoot;

        qbdsRoot = allowValuesQuery.addDataSource(attrTable.id());
        qbdsRoot.addGroupByField(attrField.id());
        qbdsRoot.addSelectionField(attrField.id());            

        var allowedValues = new Set(Types::AnyType);
        QueryRun queryRun = new SysQueryRun(allowValuesQuery);
        while(queryRun.next())
        {
            Common resultTable = queryRun.get(attrTable.id());
            str val = resultTable.(attrField.id());
            if (val != '')
            {
                allowedValues.add(val);
            }
        }

        return allowedValues;
    }
}

/// <summary>
/// Some allowed values are not human readable, and need another column as its description.
/// </summary>
/// <returns>set of GUPPricingAttributeAllowedValuesObject, Null if no description is required.</returns>
public Set getAllowedValuesWithDescription()
{
    return null;
}

 /// <summary>
 /// When not return -1, getAllowedValues() will return all symbols in that enum.
 /// And manually input is not allowed in this case -- user can only select from the enum, including default blank value.
 /// </summary>
 /// <returns>Data type (id) of a enum, -1 for non-enum (from table) price attribute.</returns>
public EnumId getFixedAllowedValueEnumId()
 {
     return ENUM_ID_NOT_EXIST;
 }

/// <summary>
/// Child class whose implementation is table field should override this method to provide correct table path.
/// </summary>
/// <remarks>General format: SalesTable#CustBankAccount_CustAccount$CustAccount#Name</remarks>
/// <returns>The table field path if table field exists; otherwise 'PATH_NOT_EXIST'.</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return PATH_NOT_EXIST;
}

public str getAttributeFieldIdentifier()
{
    // Attribute from providers.
    if(classIdGet(this) == classNum(GUPPricingAttributeEcoResAttribute))
    {
        return (this as GUPPricingAttributeEcoResAttribute).getName() +
            "_" +
            (this as GUPPricingAttributeEcoResAttribute).getAttributeType();
    }
    // Attribute from classes (as table fields).
    else
    {
        DictClass dc = new DictClass(classIdGet(this));
        GUPPricingAttributeFieldsDiscoveryAttribute attribute = (dc.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute') as GUPPricingAttributeFieldsDiscoveryAttribute);
        return attribute.parmFieldName();
    }
}
